verus! {

    /// Given three signed 8‐bit integers x, y, z satisfying
    ///   1 <= x,  1 <= y,  1 <= z,
    ///   y + 2*z <= x,
    /// returns the largest integer q (as an i8) such that
    ///   q * (y+z) <= x - z.
    /// Equivalently, q = floor((x - z)/(y + z)).
    ///
    /// The post‐condition asserts in particular that
    ///   0 <= q   and
    ///   q*(y+z) <= x-z < (q+1)*(y+z).
    spec fn solve(x: i8, y: i8, z: i8) -> i8
        requires
            // All inputs at least 1
            x >= 1 &&
            y >= 1 &&
            z >= 1 &&
            // Second input + twice third input <= first input
            y + 2*z <= x;
        ensures
            // We do our reasoning at the mathematical int level
            let X: int = x as int;
            let Y: int = y as int;
            let Z: int = z as int;
            let q: int = result as int;
            // The return is non‐negative
            0 <= q &&
            // q is the floor((X−Z)/(Y+Z))
            q * (Y + Z) <= X - Z &&
            X - Z < (q + 1) * (Y + Z);
}